parameters.jsonBody:
={
  "messaging_product": "whatsapp",
  "to": "{{ $json.body.vendor_phone }}",
  "type": "interactive",
  "interactive": {
    "type": "button",
    "header": {
      "type": "text",
      "text": "🚙 KHAKI TOURS: VENDOR DISPATCH ORDER"
    },
    "body": {
      "text": "Namaste {{ $json.body.vendor_name }}!\n\nVehicle dispatch request for Khaki Tours:\n\n• *Service:* {{ $json.body.service_name }}\n• *Vehicle Required:* {{ $json.body.vehicle_number || 'Safari Open Jeep / Boat' }}\n• *Date & Time:* {{ $json.body.scheduled_time }}\n• *Pickup Landmark:* {{ $json.body.pickup_landmark }}\n• *Guest Count:* {{ $json.body.pax_count }} Pax\n• *Contract Rate:* ₹{{ $json.body.payout_inr }}\n\nPlease confirm your availability by tapping below:"
    },
    "footer": { "text": "Khaki Logistics Desk | Zero-Login Partner Dispatch" },
    "action": {
      "buttons": [
        {
          "type": "reply",
          "reply": {
            "id": "VENDOR_CONFIRM_{{ $json.body.booking_ref }}_{{ $json.body.vendor_id }}",
            "title": "✅ Vehicle Confirmed"
          }
        },
        {
          "type": "reply",
          "reply": {
            "id": "VENDOR_UNAVAILABLE_{{ $json.body.booking_ref }}_{{ $json.body.vendor_id }}",
            "title": "❌ Unavailable / In Workshop"
          }
        }
      ]
    }
  }
}
